import ContextManager from "#core/ui/context-manager/context-manager.js";
import DialogManager, { DialogBoxID, DialogBoxOption } from "#core/ui/dialog-box/manager-dialog-box.js";
import { InterfaceMode } from "#core/ui/interface-modes/interface-modes.js";
import { NetworkUtilities } from "#core/ui/utilities/utilities-network.js";

import { LoadingStartCurtainRemoveEvent, LoadingStartCurtainRemoveName } from "#base/ui/root-game.js";

import "#base/ui-next/screens/hotseat/hotseat-curtain.jsx";

const HtmlIdHotseatCurtain = "hotseat-screen-curtain";

class MultiplayerIngameSingleton {
	private mpPauseDialogID?: DialogBoxID;

	private multiplayerGameAbandonedListener = (data: MultiplayerGameAbandonedData) => {
		this.onMultiplayerGameAbandoned(data);
	};
	private multiplayerGameLastPlayerListener: EventListener = () => {
		this.onMultiplayerGameLastPlayer();
	};
	private localPlayerChangedListener = (data: Player_EventData) => {
		this.onLocalPlayerChanged(data);
	};
	private loadingStartCurtainRemoveListener: EventListener = (event: LoadingStartCurtainRemoveEvent) => {
		this.onLoadingStartCurtainRemove(event);
	};
	private multiplayerGamePauseStateChangedListener = (data: GenericDataInt32) => {
		this.onMultiplayerPauseStatus(data);
	};

	/**
	 * CTOR
	 */
	constructor() {
		engine.whenReady.then(() => {
			this.onReady();
		});
	}

	/**
	 * Engine ready, establish callbacks.
	 */
	onReady() {
		engine.on("MultiplayerGameAbandoned", this.multiplayerGameAbandonedListener, this);
		engine.on("MultiplayerGameLastPlayer", this.multiplayerGameLastPlayerListener, this);
		engine.on("GamePauseStateChanged", this.multiplayerGamePauseStateChangedListener, this);
		engine.on("LocalPlayerChanged", this.localPlayerChangedListener, this);

		// If hotseat create the curtain before the first player's turn.
		if (Configuration.getGame().isHotseat) {
			window.addEventListener(LoadingStartCurtainRemoveName, this.loadingStartCurtainRemoveListener);
		}
	}

	/**
	 * Engine Event - multiplayer game has been abandoned (by other players?)
	 * @param data
	 */
	onMultiplayerGameAbandoned(data: MultiplayerGameAbandonedData) {
		const abandonPopup: NetworkUtilities.AbandonReasonPopup = NetworkUtilities.multiplayerAbandonReasonToPopup(
			data.reason,
		);
		DialogManager.createDialog_Confirm({
			body: abandonPopup.body,
			title: abandonPopup.title,
			callback: this.onAbandonedConfirm,
		});
	}

	/**
	 * Engine Event - Last player in the game.
	 */
	onMultiplayerGameLastPlayer() {
		// Don't display the All Alone dialog when it could break end game sequencing.
		// Directly check game over states in gamecore because it is possible that
		// the game just ended and the end game screens just haven't popped yet.
		if (ContextManager.getTarget("screen-endgame")) {
			return;
		}

		const localPlayerID: PlayerId = GameContext.localPlayerID;
		const localPlayer: PlayerLibrary | null = Players.get(localPlayerID);
		if (localPlayer && !localPlayer.isAlive) {
			return;
		}

		if (!ContextManager.isGameActive()) {
			return;
		}

		DialogManager.createDialog_Confirm({
			body: "TXT_KEY_MP_LAST_PLAYER",
			title: "TXT_KEY_MP_LAST_PLAYER_TITLE",
		});
	}

	onMultiplayerPauseStatus(data: GenericDataInt32) {
		// We don't want to display the multiplayer pause dialog when it could break end game sequencing.
		// We also directly check game over states in gamecore because it is possible that
		// the game just ended and the end game screens just haven't popped yet.

		if (ContextManager.getTarget("screen-endgame")) {
			return;
		}

		if (!ContextManager.isGameActive()) {
			return;
		}

		if (data.data == 1) {
			// The game has been paused. Throw up the pause dialog.
			if (this.mpPauseDialogID != undefined) {
				// Close the old pause dialog, it might be out of date.
				DialogManager.closeDialogBox(this.mpPauseDialogID);

				this.mpPauseDialogID = undefined;
			}

			const pauseNumPlayers: number = Network.getNumWantPausePlayers();
			const pausePlayerStr: string = Network.getWantPausePlayerName();
			let bodyText = "";
			if (pauseNumPlayers > 1) {
				bodyText = Locale.stylize("LOC_MP_PAUSE_POPUP_BODY_MULTI_WANT_PAUSE", pauseNumPlayers, pausePlayerStr);
			} else {
				bodyText = Locale.stylize("LOC_MP_PAUSE_POPUP_BODY_SINGLE_WANT_PAUSE", pausePlayerStr);
			}
			const options: DialogBoxOption[] = [];
			this.mpPauseDialogID = DialogManager.createDialog_MultiOption({
				title: "LOC_MP_PAUSE_POPUP_TITLE",
				body: bodyText,
				options: options,
				canClose: false,
				displayHourGlass: true,
			});
		} else {
			// The game is no longer paused. Hide the pause dialog if we have one.
			if (this.mpPauseDialogID != undefined) {
				DialogManager.closeDialogBox(this.mpPauseDialogID);

				this.mpPauseDialogID = undefined;
			}
		}
	}

	//===============================================================
	// Dialog Callbacks
	onAbandonedConfirm() {
		engine.call("exitToMainMenu");
	}

	/**
	 * Is the hotseat curtain up (attached to the DOM and showing?)
	 * @returns true if up, false otherwise.
	 */
	private isHotseatCurtainUp(): boolean {
		const element = document.querySelector<HTMLElement>(HtmlIdHotseatCurtain);
		if (element) {
			return true;
		}
		return false;
	}

	private attachHotseatCurtain() {
		if (!this.canAttachCurtain()) {
			return;
		}

		const curtain = document.createElement("hotseat-curtain");
		curtain.id = HtmlIdHotseatCurtain;
		// Attempt to add curtain before popup system as that's where we're adding the confirmation to continue.
		const popups = document.querySelector<HTMLDivElement>(".fxs-popups");
		if (!popups) {
			// If not found, be safe and don't add curtains as it may be covering something needed for interactions.
			return;
		}
		popups.parentElement?.insertBefore(curtain, popups);
	}

	private canAttachCurtain(): boolean {
		// Using the same rules for the ingame pause check
		return ContextManager.canOpenPauseMenu();
	}

	/**
	 * Local player changed; likely handing off game to another player (hotseat).
	 */
	private onLocalPlayerChanged(_data: Player_EventData) {
		// If hotseat create the curtain.
		if (Configuration.getGame().isHotseat) {
			// Ensure diplomacy or other modes are left before showing the curtain.
			if (!InterfaceMode.isInDefaultMode()) {
				InterfaceMode.switchToDefault();
			}
			waitForLayout(() => {
				this.attachHotseatCurtain();
			});
		}
	}

	private onLoadingStartCurtainRemove(event: LoadingStartCurtainRemoveEvent) {
		if (event.detail.id != "hotseat") {
			return;
		}
		if (Configuration.getGame().isHotseat) {
			if (!this.isHotseatCurtainUp()) {
				this.attachHotseatCurtain();
			}
		}
	}
}

const MultiplayerIngame: MultiplayerIngameSingleton = new MultiplayerIngameSingleton();
export { MultiplayerIngame as default };
